head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _24 : dummy_print (Excel 파일 인쇄 설정 옵션) 계열 중 용지 방향 / 쪽 맞춤 / 배율 / 용지 크기 옵션
//     - printSet / printSet.landScape / printSet.fitToPage / printSet.fitWidth / printSet.fitHeight
//       / printSet.scale / printSet.pageSize
//     같은 계열의 여백 + 가운데 맞춤 9 개는 _25, 머리글 / 바닥글 8 개는 _26 에서 다룬다.
//     description 은 분리 샘플 공통(_1 과 동일).
scwin.tData = {
    "description" : "[gridView > M > advancedExcelDownload]<br/>GridView 컴포넌트의 데이터를 Excel 파일로 다운로드합니다.",
    "validation" : [
        "printSet(선택) 파라미터로 Excel 파일 인쇄 관련 옵션을 객체로 설정합니다.",
        "printSet(선택) 파라미터를 생략하면 기본값 {} 이 적용됩니다.",
        "printSet.landScape(선택) 파라미터로 Excel 파일 인쇄 시 가로 방향으로 출력할지 'true'/'false' 로 설정합니다.",
        "printSet.landScape(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "printSet.fitToPage(선택) 파라미터로 Excel 파일 인쇄 시 쪽 맞춤을 사용할지 'true'/'false' 로 설정합니다.",
        "printSet.fitToPage(선택) 파라미터를 생략하면 기본값 'false' 가 적용됩니다.",
        "printSet.fitWidth(선택) 파라미터로 printSet.fitToPage 파라미터값이 'true' 일때 가로 너비를 용지 몇 장에 맞출지 설정합니다.",
        "printSet.fitWidth(선택) 파라미터를 '2' 로 설정 시 가로 최대 2장 너비에 맞게 축소되어 인쇄됩니다.",
        "printSet.fitWidth(선택) 파라미터를 생략하면 기본값 '1' 이 적용됩니다.",
        "printSet.fitHeight(선택) 파라미터로 printSet.fitToPage 파라미터값이 'true' 일때 세로 높이를 용지 몇 장에 맞출지 설정합니다.",
        "printSet.fitHeight(선택) 파라미터를 '3' 으로 설정 시 세로 최대 3장 너비에 맞게 축소되어 인쇄됩니다.",
        "printSet.fitHeight(선택) 파라미터를 생략하면 기본값 '1' 이 적용됩니다.",
        "printSet.scale(선택) 파라미터로 printSet.fitToPage 파라미터값이 'false' 일때 Excel 파일 인쇄 시 확대/축소 배율을 10~400 사잇값로 설정합니다.",
        "printSet.scale(선택) 파라미터를 생략하면 기본값 '100' 이 적용됩니다.",
        "printSet.pageSize(선택) 파라미터로 printSet.fitToPage 파라미터값이 'true' 일때 인쇄 용지의 크기를 'A3'/'A4'/'B3'/'B4' 등으로 설정합니다.",
        "printSet.pageSize(선택) 파라미터를 생략하면 기본값 'A4' 가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 : Header 1줄(병합 없음) / Body 6행 의 GridView 를 동적 생성한다.
//  · advancedExcelDownload 는 DataList 바인딩이 전제 조건이므로 dataList 속성을 반드시 설정한다.
//  · 본 계열은 Cell 값이 아니라 Excel 파일의 인쇄 설정만 바꾸므로 그리드 구성은 단순하게 둔다.
scwin.comp_init = async function () {
    // 기존 target / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제]\n- Header 는 1줄(병합 없음), Body Column 인덱스 0 부서 / 1 사원명 / 2 실적건수(number) / 3 실적금액(number), Body Row 는 6행\n- 이 계열은 Cell 값을 바꾸지 않는다. Excel 파일의 인쇄 설정만 바뀐다\n- printSet 하위 파라미터는 printSet 을 설정으로 골라야 전달된다. printSet 이 미설정이면 하위값을 골라도 전달되지 않는다\n- fitWidth / fitHeight / pageSize 는 fitToPage 가 true 일 때, scale 은 fitToPage 가 false 일 때 적용되는 값이다. 두 조건을 나누어 확인한다\n- 파일명 download_print, 확장자 xlsx, sheetName mysheet 고정 전달(본 계열 검증 대상 아님)\n[절차]\n1. par 옵션(printSet / printSet.landScape / printSet.fitToPage / printSet.fitWidth / printSet.fitHeight / printSet.scale / printSet.pageSize) 값을 선택한다\n2. advancedExcelDownload 버튼을 클릭해 Excel 파일을 내려받는다\n3. 내려받은 파일을 Excel 로 열고 페이지 레이아웃 - 페이지 설정 대화상자에서 확인한다\n[확인]\n- printSet : 미설정이면 인쇄 설정이 기본 상태 그대로인지. 설정이면 아래 항목들이 반영되는지\n- printSet.landScape : true 면 용지 방향이 가로가 되는지. false 로 설정하거나 미설정이면 세로인지\n- printSet.fitToPage : true 면 페이지 설정에서 자동 맞춤이 선택되는지. false 로 설정하거나 미설정이면 확대/축소 배율이 선택되는지\n- printSet.fitWidth : fitToPage 가 true 일 때 설정한 값(1 또는 2)이 용지 너비 장수로 들어가는지. 미설정이면 기본값 1 인지\n- printSet.fitHeight : fitToPage 가 true 일 때 설정한 값(1 또는 3)이 용지 높이 장수로 들어가는지. 미설정이면 기본값 1 인지\n- printSet.scale : fitToPage 가 false 일 때 설정한 배율(80 또는 100)이 확대/축소 배율이 되는지. 미설정이면 기본값 100 인지\n- printSet.pageSize : fitToPage 가 true 일 때 설정한 용지 크기(A3 또는 B4)가 적용되는지. 미설정이면 기본값 A4 인지\n- 파일을 압축 해제하여 xl/worksheets/sheet1.xml 의 pageSetup 요소와 pageSetUpPr 요소로도 확인할 수 있다\n- landScape 를 false 로 설정하면 생략했을 때와 결과가 같다. 세로가 기본이라 orientation 속성 자체가 기록되지 않는다\n- fitToPage 를 true 로 설정하면 fitWidth 와 fitHeight 를 주지 않아도 둘 다 기본값 1 로 함께 기록된다. fitToPage 가 false 이거나 미설정이면 pageSetUpPr 요소 자체가 없다\n- scale 을 기본값인 100 으로 설정하면 생략했을 때와 결과가 같다. scale 속성이 기록되지 않는다\n- pageSize 는 용지 코드로 저장된다. A4(기본)는 9, A3 는 8, B4 는 12 다"', '', 'label1');

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 바인딩 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="dept" name="dept" dataType="text"></w2:column>';
    strDlt += '<w2:column id="empName" name="empName" dataType="text"></w2:column>';
    strDlt += '<w2:column id="caseCnt" name="caseCnt" dataType="number"></w2:column>';
    strDlt += '<w2:column id="saleAmt" name="saleAmt" dataType="number"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "dept" : "영업기획팀", "empName" : "김도현", "caseCnt" : 34, "saleAmt" : 18450000 },
        { "dept" : "영업기획팀", "empName" : "박서연", "caseCnt" : 27, "saleAmt" : 12300000 },
        { "dept" : "고객지원팀", "empName" : "이준호", "caseCnt" : 41, "saleAmt" : 9800000 },
        { "dept" : "고객지원팀", "empName" : "최민아", "caseCnt" : 19, "saleAmt" : 6450000 },
        { "dept" : "품질관리팀", "empName" : "정우진", "caseCnt" : 25, "saleAmt" : 15200000 },
        { "dept" : "품질관리팀", "empName" : "한지민", "caseCnt" : 30, "saleAmt" : 11750000 }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 생성 (DataList 바인딩)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:700px;height:300px;">';
    strTarget += '<w2:caption style="" id="caption1" value="advancedExcelDownload (인쇄 설정 옵션 - 용지 방향 / 쪽 맞춤 / 배율 / 용지 크기) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="hcol1" value="부서"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol2" value="사원명"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol3" value="실적건수"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="실적금액"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="brow1">';
    strTarget += '<w2:column width="180" style="" inputType="text" id="dept" dataList="dept"></w2:column>';
    strTarget += '<w2:column width="150" style="" inputType="text" id="empName" dataList="empName"></w2:column>';
    strTarget += '<w2:column width="130" style="text-align:right;" inputType="text" dataType="number" id="caseCnt" dataList="caseCnt"></w2:column>';
    strTarget += '<w2:column width="*" style="text-align:right;" inputType="text" dataType="number" displayFormat="#,##0" id="saleAmt" dataList="saleAmt"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// par 옵션값으로 advancedExcelDownload options 객체를 구성한다.
//  · 선택(필수여부 N) 파라미터는 미설정(빈값) 이면 객체에 담지 않아 생략되도록 한다.
//  · printSet 하위 7 개는 모두 String 타입이므로 selectbox 값을 그대로 전달한다.
//  · fileName / extension / sheetName 은 고정값이며 본 계열의 검증 대상이 아니다.
scwin.buildOptions = function () {
    let options = { "fileName" : "download_print", "extension" : "xlsx", "sheetName" : "mysheet" };
    let arrDesc = [];

    if (par_printSet.getValue() === "") {
        return { "options" : options, "desc" : "{} (printSet 미설정)" };
    }

    let printSet = {};
    let fnSet = function (sKey, objComp) {
        let v = objComp.getValue();
        if (v !== "") {
            printSet[sKey] = v;
            arrDesc.push(sKey + "=" + v);
        }
    };

    fnSet("landScape", par_landScape);
    fnSet("fitToPage", par_fitToPage);
    fnSet("fitWidth", par_fitWidth);
    fnSet("fitHeight", par_fitHeight);
    fnSet("scale", par_scale);
    fnSet("pageSize", par_pageSize);

    options.printSet = printSet;

    return { "options" : options, "desc" : "printSet 설정" + ((arrDesc.length === 0) ? " (landScape / fitToPage / fitWidth / fitHeight / scale / pageSize 전체 생략)" : (" {" + arrDesc.join(", ") + "}")) };
}



// advancedExcelDownload 실행
scwin.btn_advancedExcelDownload_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    let objBuild = scwin.buildOptions();

    target1.advancedExcelDownload(objBuild.options);

    bottom.setReturnValue("전달 옵션 : " + objBuild.desc);
}
